  internal class MainWindow : Window {
    internal readonly Store Data;
    internal int GroupZ;
    internal readonly List<GroupCard> Cards=new List<GroupCard>();
    private readonly Dictionary<GroupData,Window> windows=new Dictionary<GroupData,Window>();
    private readonly List<FileSystemWatcher> watchers=new List<FileSystemWatcher>();
    private readonly DispatcherTimer refresh=new DispatcherTimer {Interval=TimeSpan.FromMilliseconds(350)},repair=new DispatcherTimer {Interval=TimeSpan.FromSeconds(2)};
    private readonly Dictionary<GroupData,GroupCard> cardMap=new Dictionary<GroupData,GroupCard>(); private readonly HashSet<GroupData> dirtyGroups=new HashSet<GroupData>(); private readonly DispatcherTimer saveTimer=new DispatcherTimer {Interval=TimeSpan.FromMilliseconds(180)}; private string watcherSignature;
    private Forms.NotifyIcon tray;private IntPtr host,handle;private bool closing,importing;private int ticks;
    internal bool Quiet;
    internal List<string> Pending=new List<string>();
    internal double AvailableWidth {get{return SystemParameters.WorkArea.Width;}}
    internal double AvailableHeight {get{return SystemParameters.WorkArea.Height;}}
    internal static double Dpi {get{return Math.Max(.5,Forms.Screen.PrimaryScreen.Bounds.Width/SystemParameters.PrimaryScreenWidth);}}
    internal IEnumerable<Window> GroupWindows {get{return windows.Values;}}
    internal MainWindow(Store data){Data=data;Title=L.T("Desk Bloom — группы");ShowInTaskbar=false;ShowActivated=false;WindowStyle=WindowStyle.None;Width=1;Height=1;Left=-32000;Top=-32000;Opacity=0;
      SourceInitialized+=delegate {handle=new WindowInteropHelper(this).Handle;HwndSource.FromHwnd(handle).AddHook(Hook);Win.RegisterHotKey(handle,1,0x4003,0x44);};
      Loaded+=delegate {Hide();Pending=Migration.Run(Data);host=Win.DesktopHost();RenderCurrent(false);SetupTray();refresh.Tick+=delegate {refresh.Stop();if(closing)return;if(importing){refresh.Start();return;}foreach(var group in dirtyGroups.ToList()){GroupCard card;if(cardMap.TryGetValue(group,out card))card.LoadItems(false);}dirtyGroups.Clear();};repair.Tick+=delegate {if(closing)return;ticks++;if(host==IntPtr.Zero||!Win.IsWindow(host)||ticks%15==0){IntPtr current=Win.DesktopHost();if(current!=host&&Win.IsWindow(current)){host=current;RenderCurrent(false);}}if(Pending.Count>0&&!importing&&ticks%5==0){int count=Pending.Count;Pending=Migration.Run(Data);if(count!=Pending.Count)RenderCurrent(false);}};saveTimer.Tick+=delegate {saveTimer.Stop();try {Data.Save();}catch(Exception error){Ui.Error(error);}};repair.Start();};
      Closing+=delegate(object sender,System.ComponentModel.CancelEventArgs e){if(importing){e.Cancel=true;return;}closing=true;repair.Stop();refresh.Stop();saveTimer.Stop();StopWatchers();foreach(var card in Cards)card.Dispose();Data.Save();Win.UnregisterHotKey(handle,1);foreach(var window in windows.Values.ToList())window.Close();windows.Clear();if(tray!=null){tray.Visible=false;tray.Dispose();}};
    }
    private IntPtr Hook(IntPtr hwnd,int msg,IntPtr w,IntPtr l,ref bool handled){if(msg==0x0312&&w.ToInt32()==1){ShowGroups();handled=true;}return IntPtr.Zero;}
    internal void Save(){if(closing)return;saveTimer.Stop();saveTimer.Start();}
    internal Point PointerPosition(){Win.POINT point;Win.GetCursorPos(out point);return new Point(point.X/Dpi,point.Y/Dpi);}
    internal void RenderCurrent(bool animate){if(closing)return;if(host==IntPtr.Zero)host=Win.DesktopHost();foreach(var removed in windows.Keys.Where(g=>!Data.State.Groups.Contains(g)).ToList()){cardMap[removed].Dispose();windows[removed].Close();windows.Remove(removed);cardMap.Remove(removed);}Cards.Clear();foreach(var group in Data.State.Groups){Window window;GroupCard card;bool created=!windows.TryGetValue(group,out window);if(created){window=new Window {WindowStyle=WindowStyle.None,ResizeMode=ResizeMode.NoResize,AllowsTransparency=true,Background=Brushes.Transparent,ShowInTaskbar=false,ShowActivated=false,Topmost=false,SizeToContent=SizeToContent.WidthAndHeight,WindowStartupLocation=WindowStartupLocation.Manual};if(Quiet)window.Opacity=0;windows[group]=window;window.SizeChanged+=delegate {if(!closing)PlaceDesktopGroup(group);};var area=Forms.Screen.PrimaryScreen.WorkingArea;window.Left=area.Left/Dpi+group.X-6;window.Top=area.Top/Dpi+group.Y-6;}if(created||cardMap[group].NeedsRebuild){if(!created)cardMap[group].Dispose();card=new GroupCard(this,group);cardMap[group]=card;window.Content=new Border {Padding=new Thickness(6),Child=card,Background=Brushes.Transparent};}else{card=cardMap[group];card.UpdateFromModel();}card.IsEnabled=!importing;Cards.Add(card);window.Title="Desk Bloom · "+group.Name;if(host!=IntPtr.Zero)new WindowInteropHelper(window).Owner=host;if(created)window.Show();PlaceDesktopGroup(group);if(animate&&created)Ui.Animate(card,UIElement.OpacityProperty,.3,1,220);}ClampCards();ResetWatchers();}
    internal void PlaceDesktopGroup(GroupData group){Window window;if(!windows.TryGetValue(group,out window)||!window.IsLoaded)return;var area=Forms.Screen.PrimaryScreen.WorkingArea;Win.SetWindowPos(new WindowInteropHelper(window).Handle,new IntPtr(1),area.Left+(int)Math.Round((group.X-6)*Dpi),area.Top+(int)Math.Round((group.Y-6)*Dpi),0,0,0x0051);}
    internal void RaiseDesktopGroup(GroupData group){PlaceDesktopGroup(group);}
    internal void ClampCards(){bool changed=false;foreach(var card in Cards){double x=Math.Max(6,Math.Min(card.Data.X,Math.Max(6,AvailableWidth-card.Width-12))),y=Math.Max(6,Math.Min(card.Data.Y,Math.Max(6,AvailableHeight-card.VisibleHeight-12)));changed|=x!=card.Data.X||y!=card.Data.Y;card.Data.X=x;card.Data.Y=y;PlaceDesktopGroup(card.Data);}if(changed)Save();}
    internal void NewGroup(string parent=null){try {var group=Data.CreateGroup(L.T("Новая группа"),parent);var pointer=PointerPosition();group.X=Math.Max(16,Math.Min(pointer.X,AvailableWidth-350));group.Y=Math.Max(16,Math.Min(pointer.Y,AvailableHeight-250));for(int i=0;i<60&&Data.State.Groups.Any(g=>g!=group&&new Rect(g.X,g.Y,338,g.Open?220:78).IntersectsWith(new Rect(group.X,group.Y,338,220)));i++){group.X=16+(i%Math.Max(1,(int)(AvailableWidth/350)))*348;group.Y=16+(i/Math.Max(1,(int)(AvailableWidth/350)))*230;}RenderCurrent(true);Save();}catch(Exception e){Ui.Error(e);}}
    internal void PickFiles(GroupCard card){var dialog=new OpenFileDialog {Title=L.T("Перенести файлы в группу"),Multiselect=true,CheckFileExists=true};if(dialog.ShowDialog()==true)Import(card,dialog.FileNames);}
    internal void PickFolder(GroupCard card){using(var dialog=new Forms.FolderBrowserDialog {Description=L.T("Перенести целую папку в группу")})if(dialog.ShowDialog()==Forms.DialogResult.OK)Import(card,new[]{dialog.SelectedPath});}
    internal void Import(GroupCard card,string[] sources){if(importing)return;importing=true;card.IsEnabled=false;var thread=new Thread(delegate(){var errors=new List<string>();foreach(string source in sources)try{Data.MoveIn(source,card.Data);}catch(Exception e){errors.Add(Path.GetFileName(source)+": "+e.Message);}Dispatcher.BeginInvoke(new Action(delegate {importing=false;card.IsEnabled=true;GroupCard current;if(cardMap.TryGetValue(card.Data,out current))current.LoadItems(false);RenderCurrent(false);Save();if(errors.Count>0)MessageBox.Show(string.Join("\n",errors.Take(8).ToArray()),L.T("Не все файлы удалось перенести"));}));});thread.SetApartmentState(ApartmentState.STA);thread.IsBackground=false;thread.Start();}
    internal void AddExternal(string[] sources){sources=sources.Where(p=>File.Exists(p)||Directory.Exists(p)).ToArray();if(sources.Length==0)return;if(Data.State.Groups.Count==0)NewGroup();if(Data.State.Groups.Count==0)return;
      var dialog=new Window {Title=L.T("Добавить в группу Desk Bloom"),Width=500,Height=410,WindowStartupLocation=WindowStartupLocation.CenterScreen,Background=Ui.Brush("#142136"),Foreground=Ui.Ink,Topmost=true};var dock=new DockPanel {Margin=new Thickness(22)};dialog.Content=dock;var label=Ui.Text(L.T("Выбери группу для переноса файлов"),18,Ui.Ink);label.Margin=new Thickness(0,0,0,15);DockPanel.SetDock(label,Dock.Top);dock.Children.Add(label);var list=new ListBox {ItemsSource=Data.State.Groups.Select(g=>new GroupChoice {Group=g,Name=g.Name}).ToList(),DisplayMemberPath="Name",SelectedIndex=0,Background=Ui.Brush("#22324A"),Foreground=Ui.Ink,FontSize=15};GroupData selected=null;Action accept=delegate {var choice=list.SelectedItem as GroupChoice;selected=choice==null?null:choice.Group;if(selected!=null)dialog.DialogResult=true;};var bottom=new StackPanel {Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,16,0,0)};bottom.Children.Add(Ui.Button(L.T("Отмена"),delegate {dialog.Close();},false));bottom.Children.Add(Ui.Button(L.T("Перенести"),accept,true));DockPanel.SetDock(bottom,Dock.Bottom);dock.Children.Add(bottom);dock.Children.Add(list);list.MouseDoubleClick+=delegate {accept();};dialog.KeyDown+=delegate(object s,KeyEventArgs e){if(e.Key==Key.Escape)dialog.Close();else if(e.Key==Key.Enter)accept();};if(dialog.ShowDialog()==true&&selected!=null){selected.Open=true;RenderCurrent(false);Import(Cards.First(c=>c.Data==selected),sources);}
    }
    private class GroupChoice {internal GroupData Group;public string Name {get;set;}}
    internal void ReturnFile(GroupCard card,string path){try{Directory.CreateDirectory(Data.Desktop);string destination=Store.Unique(Data.Desktop,Path.GetFileName(path));if(Directory.Exists(path))FileSystem.MoveDirectory(path,destination,UIOption.OnlyErrorDialogs);else FileSystem.MoveFile(path,destination,UIOption.OnlyErrorDialogs);card.LoadItems(true);}catch(Exception e){Ui.Error(e);}}
    internal void RenameReadableGroup(GroupData group,string name){try{Migration.MoveGroup(Data,group,Path.GetDirectoryName(Data.GroupPath(group)),name);RenderCurrent(false);}catch(Exception e){Ui.Error(e);}}
    internal void RelocateReadableGroup(GroupData group){using(var dialog=new Forms.FolderBrowserDialog {Description=L.T("Где хранить обычную папку группы?"),SelectedPath=Path.GetDirectoryName(Data.GroupPath(group))})if(dialog.ShowDialog()==Forms.DialogResult.OK)try{Migration.MoveGroup(Data,group,dialog.SelectedPath,group.Name);RenderCurrent(false);}catch(Exception e){Ui.Error(e);}}
    internal void RemoveGroup(GroupData group){if(MessageBox.Show(L.T("Убрать панель группы? Файлы останутся в папке:\n")+Data.GroupPath(group),"Desk Bloom",MessageBoxButton.YesNo,MessageBoxImage.Question)==MessageBoxResult.Yes){PortableLayouts.Detach(Data,group);RenderCurrent(false);}}
    private void StopWatchers(){foreach(var watcher in watchers)watcher.Dispose();watchers.Clear();watcherSignature=null;}
    private void Changed(GroupData group){if(!closing)Dispatcher.BeginInvoke(new Action(delegate {if(closing)return;dirtyGroups.Add(group);refresh.Stop();refresh.Start();}));}
    private bool OwnMetadata(GroupData group,string path){string name=Path.GetFileName(path),doc=Store.SafeName(group.Name)+".groups";return string.Equals(name,doc,StringComparison.OrdinalIgnoreCase)||string.Equals(name,doc+".tmp",StringComparison.OrdinalIgnoreCase);}
    private void ResetWatchers(){string signature=string.Join("|",Data.State.Groups.Select(g=>g.Id+":"+Data.GroupPath(g)).OrderBy(s=>s));if(signature==watcherSignature)return;StopWatchers();watcherSignature=signature;foreach(var group in Data.State.Groups){string folder=Data.GroupPath(group);if(!Directory.Exists(folder))continue;var watched=group;var watcher=new FileSystemWatcher(folder){NotifyFilter=NotifyFilters.FileName|NotifyFilters.DirectoryName|NotifyFilters.LastWrite|NotifyFilters.Size};FileSystemEventHandler changed=delegate(object sender,FileSystemEventArgs e){if(!OwnMetadata(watched,e.FullPath))Changed(watched);};watcher.Created+=changed;watcher.Deleted+=changed;watcher.Changed+=changed;watcher.Renamed+=delegate(object sender,RenamedEventArgs e){changed(sender,e);};watcher.Error+=delegate {Changed(watched);};watcher.EnableRaisingEvents=true;watchers.Add(watcher);}foreach(string parent in Data.State.Groups.Select(g=>Path.GetDirectoryName(Data.GroupPath(g))).Where(Directory.Exists).Distinct(StringComparer.OrdinalIgnoreCase)){var watcher=new FileSystemWatcher(parent){NotifyFilter=NotifyFilters.DirectoryName};watcher.Renamed+=delegate(object sender,RenamedEventArgs e){if(!closing)Dispatcher.BeginInvoke(new Action(delegate {if(closing)return;bool renamed=false;foreach(var group in Data.State.Groups)if(string.Equals(Data.GroupPath(group),e.OldFullPath,StringComparison.OrdinalIgnoreCase)){group.FolderPath=e.FullPath;group.Name=Path.GetFileName(e.FullPath);if(Appearance.Plain(group.TitleParts)!=group.Name)group.TitleParts=null;renamed=true;}if(renamed){RenderCurrent(false);Save();}}));};watcher.EnableRaisingEvents=true;watchers.Add(watcher);}}
    internal void ChangeLanguage(string language){if(language!="ru"&&language!="en")return;Data.State.Language=language;L.Language=language;Title=L.T("Desk Bloom — группы");saveTimer.Stop();Data.Save();if(Data.Production)ShellIntegration.Install(Data);if(tray!=null)tray.Text=L.T("Desk Bloom · группы");RenderCurrent(false);}
    internal Forms.ContextMenuStrip BuildTrayMenu(){var menu=new Forms.ContextMenuStrip();FillTrayMenu(menu);return menu;}
    private void FillTrayMenu(Forms.ContextMenuStrip menu){foreach(Forms.ToolStripItem item in menu.Items.Cast<Forms.ToolStripItem>().ToArray())item.Dispose();menu.Items.Clear();menu.Items.Add(L.T("Создать группу"),null,delegate {Dispatcher.BeginInvoke(new Action(delegate {NewGroup();}));});menu.Items.Add(L.T("Показать группы на рабочем столе"),null,delegate {Dispatcher.BeginInvoke(new Action(ShowGroups));});var all=new Forms.ToolStripMenuItem(L.T("Мои группы"));foreach(var group in Data.State.Groups){var selected=group;all.DropDownItems.Add(group.Name,null,delegate {Dispatcher.BeginInvoke(new Action(delegate {selected.Open=true;Save();ShowGroups();}));});}menu.Items.Add(all);menu.Items.Add(L.T("Открыть папки групп"),null,delegate {Ui.Open(Data.GroupsRoot);});menu.Items.Add(new Forms.ToolStripSeparator());var languages=new Forms.ToolStripMenuItem("Язык / Language");var russian=new Forms.ToolStripMenuItem("Русский"){Checked=L.Language=="ru"};russian.Click+=delegate {ChangeLanguage("ru");};var english=new Forms.ToolStripMenuItem("English"){Checked=L.Language=="en"};english.Click+=delegate {ChangeLanguage("en");};languages.DropDownItems.Add(russian);languages.DropDownItems.Add(english);menu.Items.Add(languages);var startup=new Forms.ToolStripMenuItem(L.T("Запускать вместе с Windows")){Checked=ShellIntegration.StartupEnabled()};startup.Click+=delegate {ShellIntegration.Startup(!ShellIntegration.StartupEnabled());};menu.Items.Add(startup);menu.Items.Add(L.T("Выход"),null,delegate {Dispatcher.BeginInvoke(new Action(Close));});}
    private void SetupTray(){if(Quiet)return;tray=new Forms.NotifyIcon {Icon=System.Drawing.Icon.ExtractAssociatedIcon(Assembly.GetExecutingAssembly().Location),Text=L.T("Desk Bloom · группы"),Visible=true};var menu=new Forms.ContextMenuStrip();menu.Opening+=delegate {FillTrayMenu(menu);};tray.ContextMenuStrip=menu;tray.DoubleClick+=delegate {Ui.Open(Data.GroupsRoot);};}
    internal void ShowGroups(){object shell=null;try{shell=Activator.CreateInstance(Type.GetTypeFromProgID("Shell.Application"));shell.GetType().InvokeMember("MinimizeAll",BindingFlags.InvokeMethod,null,shell,null);}finally{if(shell!=null)Marshal.FinalReleaseComObject(shell);}var timer=new DispatcherTimer {Interval=TimeSpan.FromMilliseconds(450)};timer.Tick+=delegate {timer.Stop();RenderCurrent(false);};timer.Start();}
    internal void HandleDesktopRequest(string[] paths){if(paths.Length==0){ShowGroups();return;}switch(paths[0]){case "@language":if(paths.Length>1)ChangeLanguage(paths[1]);return;case "@exit":Close();return;case "@new-group":NewGroup();return;case "@new-group-in":if(paths.Length>1)NewGroup(paths[1]);return;case "@show-desktop":ShowGroups();return;case "@open-layout":if(paths.Length>1)try{PortableLayouts.Import(Data,paths[1]);RenderCurrent(false);ShowGroups();}catch(Exception e){Ui.Error(e);}return;case "@verify":if(paths.Length>1)Verify(paths[1]);return;}AddExternal(paths);}
    internal void Verify(string path){ShowGroups();var timer=new DispatcherTimer {Interval=TimeSpan.FromMilliseconds(1800)};timer.Tick+=delegate {timer.Stop();var screen=Forms.Screen.PrimaryScreen.Bounds;using(var bitmap=new System.Drawing.Bitmap(screen.Width,screen.Height))using(var graphics=System.Drawing.Graphics.FromImage(bitmap)){graphics.CopyFromScreen(screen.Left,screen.Top,0,0,screen.Size);bitmap.Save(path,System.Drawing.Imaging.ImageFormat.Png);}File.WriteAllText(path+".status.txt","Groups="+windows.Count+"; NativeIconsVisible="+Win.IsWindowVisible(Win.IconView()));};timer.Start();}
  }
  internal static class ShellIntegration {
    internal static string Executable {get{return "\""+Assembly.GetExecutingAssembly().Location+"\"";}}
    internal static void Install(Store data){foreach(string kind in new[]{"*","Directory"})using(var key=Registry.CurrentUser.CreateSubKey("Software\\Classes\\"+kind+"\\shell\\DeskBloom.Add")){key.SetValue("",L.T("Добавить в группу Desk Bloom…"));key.SetValue("Icon",Executable+",0");key.SetValue("MultiSelectModel","Single");using(var command=key.CreateSubKey("command"))command.SetValue("",Executable+" --add \"%1\"");}
      foreach(string kind in new[]{"DesktopBackground","Directory\\Background"})using(var key=Registry.CurrentUser.CreateSubKey("Software\\Classes\\"+kind+"\\shell\\DeskBloom.NewGroup")){key.SetValue("",kind=="DesktopBackground"?L.T("Создать группу Desk Bloom"):L.T("Создать группу Desk Bloom в этой папке"));key.SetValue("Icon",Executable+",0");using(var command=key.CreateSubKey("command"))command.SetValue("",Executable+(kind=="DesktopBackground"?" --new-group":" --new-group-in \"%V\""));}
      Registry.CurrentUser.DeleteSubKeyTree("Software\\Classes\\DesktopBackground\\shell\\DeskBloom.Pages",false);Registry.CurrentUser.DeleteSubKeyTree("Software\\Classes\\DeskBloom.Desktop",false);using(var desk=Registry.CurrentUser.OpenSubKey("Software\\Classes\\.desk",true))if(desk!=null&&(desk.GetValue("") as string)=="DeskBloom.Desktop")desk.DeleteValue("",false);
      using(var ext=Registry.CurrentUser.CreateSubKey("Software\\Classes\\.groups"))ext.SetValue("","DeskBloom.Group");using(var type=Registry.CurrentUser.CreateSubKey("Software\\Classes\\DeskBloom.Group")){type.SetValue("",L.T("Группа Desk Bloom"));using(var icon=type.CreateSubKey("DefaultIcon"))icon.SetValue("",Executable+",0");using(var command=type.CreateSubKey("shell\\open\\command"))command.SetValue("",Executable+" --open-layout \"%1\"");}
      if(StartupEnabled())Startup(true);using(var worker=Process.Start(new ProcessStartInfo(Assembly.GetExecutingAssembly().Location,"--integrate-folders \""+data.GroupsRoot+"\""){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden})){}Win.SHChangeNotify(0x08000000,0,IntPtr.Zero,IntPtr.Zero);
    }
    internal static int IntegrateFolders(string groupsRoot){try{string documents=Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments);foreach(string folder in Directory.GetDirectories(documents,"Рабочий стол *"))if(File.Exists(Path.Combine(folder,".deskbloom-page")))FolderPresentation.Unpin(folder);return FolderPresentation.Pinned(groupsRoot)||FolderPresentation.Pin(groupsRoot)?0:1;}catch{return 1;}}
    internal static bool StartupEnabled(){using(var key=Registry.CurrentUser.OpenSubKey("Software\\Microsoft\\Windows\\CurrentVersion\\Run"))return key!=null&&key.GetValue("DeskBloom")!=null;}
    internal static void Startup(bool enabled){using(var key=Registry.CurrentUser.CreateSubKey("Software\\Microsoft\\Windows\\CurrentVersion\\Run"))if(enabled)key.SetValue("DeskBloom",Executable);else key.DeleteValue("DeskBloom",false);}
  }
  internal static class Program {
    [STAThread] internal static int Main(string[] args){
      RenderOptions.ProcessRenderMode=RenderMode.SoftwareOnly;
#if DIAGNOSTICS
      if(args.Length>=2&&args[0]=="--memory-test")return MemoryProbe.Run(args[1],args.Length>2?args[2]:"software");
      if(args.Length>1&&args[0]=="--perf-test")return Perf.Run(args[1],args.Length>2?args[2]:"small");
      if(args.Length>1&&args[0]=="--self-test")return Tests.Run(args[1]);
      if(args.Length>1&&args[0]=="--demo-screenshots")return Demo.Render(args[1],args.Length>2?args[2]:"en");
#endif
      if(args.Length==2&&args[0]=="--integrate-folders")return ShellIntegration.IntegrateFolders(args[1]);
      if(args.Any(a=>a=="--self-test"||a=="--perf-test"||a=="--memory-test"||a=="--demo-screenshots"))return 2;
      string root=null;bool waitForExit=false;var incoming=new List<string>();for(int i=0;i<args.Length;i++)switch(args[i]){case "--language":if(i+1<args.Length){incoming.Add("@language");incoming.Add(args[++i]);}break;case "--data":if(i+1<args.Length)root=args[++i];break;case "--exit":incoming.Add("@exit");break;case "--wait-exit":incoming.Add("@exit");waitForExit=true;break;case "--new-group":incoming.Add("@new-group");break;case "--new-group-in":if(i+1<args.Length){incoming.Add("@new-group-in");incoming.Add(args[++i]);}break;case "--open-layout":if(i+1<args.Length){incoming.Add("@open-layout");incoming.Add(args[++i]);}break;case "--add":if(i+1<args.Length)incoming.Add(args[++i]);break;case "--show-desktop":incoming.Add("@show-desktop");break;case "--verify-desktop":if(i+1<args.Length){incoming.Add("@verify");incoming.Add(args[++i]);}break;}
      if(root==null)root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"DeskBloom");string token=Convert.ToBase64String(System.Security.Cryptography.SHA256.Create().ComputeHash(Encoding.UTF8.GetBytes(Path.GetFullPath(root).ToLowerInvariant()))).Replace('/','_').Replace('+','_').Substring(0,16);bool first;using(var mutex=new Mutex(true,"Local\\DeskBloom."+token,out first)){if(!first){if(!RequestQueue.Enqueue(root,token,incoming))return 1;if(waitForExit){try{if(!mutex.WaitOne(15000))return 3;}catch(AbandonedMutexException){}mutex.ReleaseMutex();}return 0;}if(incoming.Count==1&&incoming[0]=="@exit")return 0;try{var store=new Store(root);if(store.Production)ShellIntegration.Install(store);var app=new Application {ShutdownMode=ShutdownMode.OnMainWindowClose};app.DispatcherUnhandledException+=delegate(object sender,DispatcherUnhandledExceptionEventArgs e){Ui.Error(e.Exception);e.Handled=true;};var main=new MainWindow(store){Quiet=args.Contains("--quiet-test")&&!store.Production};if(incoming.Count>0)RequestQueue.Enqueue(root,token,incoming);using(var queue=new RequestQueue(root,token,main))app.Run(main);return 0;}catch(Exception e){Ui.Error(e);return 1;}}
    }
  }
}
